package com.bank.audit;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TraversalDemo {

    private static final Logger log = Logger.getLogger(TraversalDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build: root "D" with left "B" (A,C children) and right "F" (E,G children).
        ApprovalNode a = new ApprovalNode("A", null, null);
        ApprovalNode c = new ApprovalNode("C", null, null);
        ApprovalNode e = new ApprovalNode("E", null, null);
        ApprovalNode g = new ApprovalNode("G", null, null);
        ApprovalNode b = new ApprovalNode("B", a, c);
        ApprovalNode f = new ApprovalNode("F", e, g);
        ApprovalNode d = new ApprovalNode("D", b, f);

        ApprovalTree tree = new ApprovalTree();

        log.info("INORDER (sorted roster, L-Node-R):");
        tree.inorder(d);
        log.info("PREORDER (top-down export, Node-L-R):");
        tree.preorder(d);
        log.info("POSTORDER (safe teardown, L-R-Node):");
        tree.postorder(d);
        log.info("LEVEL-ORDER (by depth, BFS):");
        tree.levelOrder(d);
    }
}

