class ApprovalNode {
    final String name;
    final ApprovalNode left;
    final ApprovalNode right;
    ApprovalNode(String name, ApprovalNode left, ApprovalNode right) {
            this.name = name;
            this.left = left
            this.right = right;
    }
}

// ─── Would be in service/ApprovalTree.java in a real project ───
class ApprovalTree {

    private static final Logger log = Logger.getLogger(ApprovalTree.class.getName());

    void inorder(ApprovalNode n) {
        if (n == null) return;
        inorder(n.left);
        log.info(() -> "Visit " + n.name);
        inorder(n.right);
    }

    void preorder(ApprovalNode n) {
        if (n == null) return;
        log.info(() -> "Visit " + n.name);
        preorder(n.left);
        preorder(n.right);
    }

    void postorder(ApprovalNode n) {
        if (n == null) return;
        postorder(n.left);
        postorder(n.right);
        log.info(() -> "Visit " + n.name);
    }

    // Level-order uses a queue (breadth-first).
    void levelOrder(ApprovalNode root) {
        if (root == null) return;
        java.util.Queue<ApprovalNode> queue = new java.util.LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            ApprovalNode n = queue.poll();
            log.info(() -> "Visit " + n.name);
            if (n.left != null) queue.offer(n.left);
            if (n.right != null) queue.offer(n.right);
        }
    }
}

